from taf.ul.ettf.msg_capture.capture_condition_tracker import ConditionNotMet
from taf.ul.ettf.msg_capture.condition_wrappers.condition import Condition, Verifiable
from taf.ul.ettf.msg_capture.condition_wrappers.utils import PartialMatch, get_matchers_with_tags, WrongOrderError, \
    UNEXPECTED_PACKET_MISMATCH, UNEXISTING_PACKET, UNEXISTING_RESULT
from taf.ul.ettf.msg_capture.expectation_builders import Expected
from taf.ul.ettf.ta_matchers.matchers import MatchingError, MatchingResult, Mismatch
from taf.ul.ettf.logger import custom_logger

logger = custom_logger('Ordered')


class Ordered(Condition, Verifiable):
    def __init__(self, *matchers):
        self._expected_matchers = get_matchers_with_tags(matchers, Expected.tags)
        self._all_matchers = get_matchers_with_tags(matchers, [])
        self._used_matchers = []
        self._callbacks = []

    def __eq__(self, other):
        if not isinstance(other, Ordered):
            return False
        return self.matchers == other.matchers

    @property
    def matchers(self):
        return self._all_matchers

    def get_name(self):
        return 'With order'

    def _run_callbacks_for_unused_matchers(self):
        for matcher in self._get_unused_matchers():
            for callback in self._callbacks:
                callback(matcher, UNEXISTING_PACKET, UNEXISTING_RESULT)
                self._used_matchers.append(matcher)

    def _get_unused_matchers(self):
        return [m for m in self._expected_matchers if m not in self._used_matchers]

    def verify(self, packets):
        sorted_by_timestamps = sorted(packets, key=lambda msg: msg.timestamp)

        for captured_message in sorted_by_timestamps:
            if self._no_matchers_left():
                return
            self.validate(captured_message)

        if self._get_final_result():
            return

        self._run_callbacks_for_unused_matchers()
        raise WrongOrderError('Unexpected order of captured messages!')

    def append_callback(self, callback):
        self._callbacks.append(callback)
        for m in self._expected_matchers:
            m.append_callback(callback)

    def validate(self, packet):
        if self._no_matchers_left():
            raise MatchingError([Mismatch('Matcher is empty!')])

        expected_matcher = self._expected_matchers[0] if self._expected_matchers else None
        matcher = self._all_matchers[0]

        local_mismatches = []
        offset = 0
        while expected_matcher != matcher:
            local_mismatches.extend(self._match_packet_as_unexpected(packet, matcher))
            if local_mismatches:
                raise ConditionNotMet(local_mismatches)
            offset += 1
            if len(self._all_matchers) > offset:
                matcher = self._all_matchers[offset]
            else:
                return MatchingResult([])

        self._used_matchers.append(expected_matcher)
        try:
            self._match_packet(expected_matcher, packet)
            self._packet_matched(offset)

            if self._no_matchers_left():
                return MatchingResult([])

            return PartialMatch()
        except MatchingError as error:
            return MatchingResult([error.mismatches])

    def _packet_matched(self, offset):
        self._expected_matchers = self._expected_matchers[1:]
        self._all_matchers = self._all_matchers[offset + 1:]

    def _match_packet_as_unexpected(self, packet, matcher):
        local_mismatches = []
        try:
            matcher.match(packet)
            local_mismatches.append(UNEXPECTED_PACKET_MISMATCH)
            for callback in self._callbacks:
                callback(matcher, packet, MatchingResult(local_mismatches))
        except MatchingError:
            pass

        return local_mismatches

    def _no_matchers_left(self):
        return not self._all_matchers

    def _get_final_result(self):
        return not self._expected_matchers
